response = client.beta.messages.create(
    model="claude-opus-5-5",
    max_tokens=4096,
    messages=[{"role": "user", "content": "Create a simple command line calculator app using Python"}],
    tools=[
        {"type": "text_editor_20250728", "name": "str_replace_based_edit_tool", "max_characters": 10000},
        {"type": "web_search_20250305", "name": "web_search", "max_uses": 3},
    ],
    betas=["context-management-2025-06-27"],
    context_management={
        "edits": [{
            "type": "clear_tool_uses_20250919",
            "trigger": {"type": "input_tokens", "value": 30000},
            "keep": {"type": "tool_uses", "value": 3},
            "clear_at_least": {"type": "input_tokens", "value": 5000},
            "exclude_tools": ["web_search"],
        }]
    },
)

// Request tool config
{"type": "memory_20250818", "name": "memory"}

// Claude asks to look at memory
{"type": "tool_use", "id": "toolu_01C4...", "name": "memory",
 "input": {"command": "view", "path": "/memories"}}

// Your app replies
{"type": "tool_result", "tool_use_id": "toolu_01C4...",
 "content": "Here're the files and directories up to 2 levels deep in /memories..."}
